const player=new T.Vector3(-44,0,63);let yaw=.08,pitch=-.08,keys=new Set(),verticalVelocity=0,jumpHeight=0,nearest=null,toastTimer,drag=null,dragDistance=0,touchMove={x:0,y:0},touchLook=null,panels=['settings','mapPanel','helpPanel'];
