let mapPoints=[];function drawMap(){if(!initialized)return;let c=$('mapCanvas'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.fillStyle='#dbe3d0';ctx.fillRect(0,0,w,h);const bounds={minX:-450,maxX:330,minZ:-680,maxZ:230},sx=x=>(x-bounds.minX)/(bounds.maxX-bounds.minX)*w,sz=z=>(z-bounds.minZ)/(bounds.maxZ-bounds.minZ)*h;
 for(let y=0;y<h;y+=5)for(let x=0;x<w;x+=5){let xx=mix(bounds.minX,bounds.maxX,x/w),zz=mix(bounds.minZ,bounds.maxZ,y/h),el=elevation(xx,zz);ctx.fillStyle=el>250?'#e8eae0':el>150?'#bdc6b4':el>65?'#a0b39a':lakeDistance(xx,zz)<1?'#82adb0':zz>15&&Math.abs(xx-streamX(zz))<8?'#92b7b2':'#d3dfc2';ctx.fillRect(x,y,5,5);if(el>60&&Math.floor(el/25)!==Math.floor(elevation(xx+5,zz)/25)){ctx.fillStyle='#758e7545';ctx.fillRect(x,y,3,1)}}
 ctx.strokeStyle='#a5b18d';ctx.lineWidth=2;ctx.setLineDash([4,5]);ctx.beginPath();for(let i=0;i<=30;i++){let t=i/30;ctx.lineTo(sx(mix(-70,-260,t)+Math.sin(t*8)*20),sz(mix(50,-470,t)))}ctx.stroke();ctx.setLineDash([]);ctx.font='12px serif';ctx.fillStyle='#5e7555';ctx.fillText('N ↑',w-42,30);ctx.font='11px serif';ctx.fillStyle='#83917e';ctx.fillText('雪 山 山 脉',sx(-160),45);
 mapPoints=destinations.map(d=>({d,x:sx(d.x),y:sz(d.z)}));for(let {d,x,y} of mapPoints){ctx.fillStyle='#f3f3e8';ctx.strokeStyle='#7d9671';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,6,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle='#405c3d';ctx.font='12px serif';ctx.textAlign='center';ctx.fillText(d.name,x,y-14)}
 if(state.entered){let x=sx(player.x),y=sz(player.z);ctx.fillStyle='#b87751';ctx.beginPath();ctx.arc(x,y,5,0,TAU);ctx.fill();ctx.strokeStyle='#b87751';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-Math.sin(yaw)*14,y-Math.cos(yaw)*14);ctx.stroke()}ctx.textAlign='start';}
$('mapCanvas').addEventListener('click',e=>{let r=e.currentTarget.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*e.currentTarget.width,y=(e.clientY-r.top)/r.height*e.currentTarget.height;let p=mapPoints.find(p=>Math.hypot(x-p.x,y-p.y)<28);if(p)goTo(p.d.id)});

function tone(freq,duration,volume=.025){if(!audio||!ambientGain)return;let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.85,audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(g).connect(ambientGain);o.start();o.stop(audio.currentTime+duration)}
async function toggleAudio(){if(!audio){try{audio=new(window.AudioContext||window.webkitAudioContext)();ambientGain=audio.createGain();ambientGain.gain.value=.45;ambientGain.connect(audio.destination);let buffer=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate),data=buffer.getChannelData(0),r=rng(78),brown=0;for(let i=0;i<data.length;i++){brown=(brown+(r()*2-1)*.025)/1.025;data[i]=brown*3}let source=audio.createBufferSource();source.buffer=buffer;source.loop=true;let filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=400;windGain=audio.createGain();windGain.gain.value=.3;source.connect(filter).connect(windGain).connect(ambientGain);source.start();let waterSrc=audio.createBufferSource();waterSrc.buffer=buffer;waterSrc.loop=true;let waterFilter=audio.createBiquadFilter();waterFilter.type='highpass';waterFilter.frequency.value=1200;riverGain=audio.createGain();riverGain.gain.value=.1;waterSrc.connect(waterFilter).connect(riverGain).connect(ambientGain);waterSrc.start();}catch{toast('当前浏览器无法播放自然音');return}}state.audio=!state.audio;if(state.audio){await audio.resume();ambientGain.gain.setTargetAtTime(.45,audio.currentTime,.3);$('soundBtn').style.opacity='1';$('soundBtn').setAttribute('aria-label','关闭自然音');toast('自然音已开启 · 山风、水声与鸟鸣')}else{ambientGain.gain.setTargetAtTime(0,audio.currentTime,.3);$('soundBtn').style.opacity='.4';$('soundBtn').setAttribute('aria-label','开启自然音')}}
function updateAudio(dt,day){if(!audio||audio.state!=='running')return;let waterDist=Math.min(Math.abs(player.x-streamX(player.z)),Math.abs(lakeDistance(player.x,player.z)-1)*70);riverGain.gain.setTargetAtTime(.03+Math.max(0,1-waterDist/35)*.65+(state.weather==='rain'?.45:0),audio.currentTime,1);windGain.gain.setTargetAtTime(.18+(state.weather==='clear'?0:.22)+Math.max(0,elevation(player.x,player.z)-150)/200,audio.currentTime,1);if(elapsed>nextBird&&day>.3&&state.weather!=='rain'){nextBird=elapsed+8+Math.random()*16;tone(2200+Math.random()*700,.14,.025);setTimeout(()=>{if(state.audio)tone(2800,.12,.02)},180)} }

